import {
  LESSON_CELL_CHUNKS,
  LESSON_EPISODES,
  LESSON_HEADER_CHUNKS,
  LESSON_QUESTS,
  LESSON_TEACHES,
  LESSON_TITLE_CHUNKS,
  loadLessonCell,
  loadLessonHeaders,
  loadLessonTitles,
} from './__generated__/lessons-index';
import { createLessonStore, episodesOverStore, questsOverStore } from '../logic/lessons/lesson-store';
import { abandonPendingChunk } from '../platform/lesson-chunk-abandon';

/**
 * The shipped upper-stage lesson cells (F-CURR-001 §3.10), generated by
 * scripts/build-lessons.mjs from content/episodes/stage-<n>/*.json, a cell's Volume 2 included
 * (`<theme>.v2.json`, F-CURR-002 row CM-40). The manifest (episodes and quest headers, English ids,
 * titles and minutes) loads at start; a cell's (or volume's) steps, scopes and glosses load on demand
 * from its content-hashed chunk, the es / ko titles from the active locale's title chunk, and the
 * display lines (an episode's subtitle, Hoya intro and reward cards, a quest's blurb and teaser) from
 * one headers chunk per locale, English included (F-CURR-002 §10, rows CM-5 and CM-40).
 * `lessonContent` is the store the screens wait on.
 */
/**
 * How long the first screen, or a newly chosen locale, waits for the locale's lesson titles and headers (F-CURR-002
 * §10): past that, the screens show with the lesson titles and display lines in English, or, while the English
 * headers are not in either, without the display lines, and draw them again when the chunks arrive.
 */
export const TITLES_GRACE_MS = 2_500;

export const lessonContent = createLessonStore(
  { episodes: LESSON_EPISODES, cells: LESSON_CELL_CHUNKS, titles: LESSON_TITLE_CHUNKS, headers: LESSON_HEADER_CHUNKS },
  { cell: loadLessonCell, titles: loadLessonTitles, headers: loadLessonHeaders },
  {
    // A chunk comes from the precache in a frame or two; a request that hangs fails into the retry path,
    // and its pending script is given up so the retry asks again.
    timeoutMs: 15_000,
    abandon: (bundleName) => {
      abandonPendingChunk(bundleName);
    },
    // A locale's titles that take longer than this (no worker in control on a slow network) wait no more:
    // the screens show in that locale with the lesson titles in English until the chunk arrives.
    titlesGraceMs: TITLES_GRACE_MS,
  },
);

/** The lesson episodes; an episode's display lines read the English headers chunk, which the first screen waits for. */
export const lessonEpisodes = episodesOverStore(LESSON_EPISODES, lessonContent);

/**
 * The lesson quests; a quest's `steps` read its cell's chunk, so they are empty until `lessonContent` has it, and its
 * blurb and teaser read the English headers chunk.
 */
export const lessonQuests = questsOverStore(LESSON_QUESTS, lessonContent);

/**
 * The jamo ids a lesson quest's Discover step teaches, from the manifest, so they are there before
 * its chunk loads (a closed quest's letters on the lesson page, the results teaser, the placement
 * catalogue); undefined for a quest that is not a lesson quest.
 */
export function lessonQuestTeaches(questId: string): readonly string[] | undefined {
  if (lessonContent.cellOfQuest(questId) === undefined) return undefined;
  return LESSON_TEACHES[questId] ?? [];
}
